<template><main class="virtual-page"><header><div><h1>虚拟比赛</h1><p>使用公开题目创建独立计时练习</p></div><ElButton type="primary" @click="dialog=true">新建虚拟赛</ElButton></header><div class="layout"><aside><button v-for="item in sessions" :key="item.id" :class="{active:selected?.session.id===item.id}" @click="open(item.id)"><strong>{{item.title}}</strong><span>{{item.solvedProblems}} / {{item.totalProblems}} · {{item.status}}</span></button></aside><section v-if="selected"><div class="session-head"><h2>{{selected.session.title}}</h2><strong>{{countdown}}</strong></div><ElTable :data="selected.problems" row-key="problemId"><ElTableColumn prop="position" label="#" width="60"/><ElTableColumn prop="title" label="题目"/><ElTableColumn prop="attempts" label="尝试" width="80"/><ElTableColumn label="状态" width="90"><template #default="{row}"><ElTag :type="row.solved?'success':'info'">{{row.solved?'已通过':'未通过'}}</ElTag></template></ElTableColumn><ElTableColumn width="90"><template #default="{row}"><RouterLink :to="`/practice?virtualSessionId=${selected?.session.id}&problemId=${row.problemId}`">作答</RouterLink></template></ElTableColumn></ElTable></section><ElEmpty v-else description="暂无虚拟赛"/></div><ElDialog v-model="dialog" title="新建虚拟赛" width="min(620px,92vw)"><ElForm label-position="top"><ElFormItem label="名称"><ElInput v-model="form.title" maxlength="255"/></ElFormItem><ElFormItem label="时长（分钟）"><ElInputNumber v-model="form.durationMinutes" :min="15" :max="10080"/></ElFormItem><ElFormItem label="题目"><ElSelect v-model="form.problemIds" multiple filterable style="width:100%"><ElOption v-for="item in problems" :key="item.id" :label="`${item.slug} · ${item.title}`" :value="item.id"/></ElSelect></ElFormItem></ElForm><template #footer><ElButton @click="dialog=false">取消</ElButton><ElButton type="primary" @click="create">开始</ElButton></template></ElDialog></main></template>
<script setup lang="ts">import{computed,onBeforeUnmount,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{getErrorMessage}from'../api/client';import{trainingApi,type BankProblem,type VirtualSession,type VirtualSessionDetail}from'../api/training';const sessions=ref<VirtualSession[]>([]),selected=ref<VirtualSessionDetail>(),problems=ref<BankProblem[]>([]),dialog=ref(false),now=ref(Date.now()),form=reactive({title:'个人虚拟赛',durationMinutes:300,problemIds:[] as number[]});let timer:number|undefined;const countdown=computed(()=>{if(!selected.value)return'--:--:--';const seconds=Math.max(0,Math.floor((new Date(selected.value.session.endAt).getTime()-now.value)/1000));return[Math.floor(seconds/3600),Math.floor(seconds%3600/60),seconds%60].map(v=>String(v).padStart(2,'0')).join(':')});async function open(id:number){try{selected.value=await trainingApi.virtualSession(id)}catch(e){ElMessage.error(getErrorMessage(e))}}async function load(){try{const[list,bank]=await Promise.all([trainingApi.virtualSessions(),trainingApi.problemBank(0,100)]);sessions.value=list;problems.value=bank.content;if(!selected.value&&list[0])await open(list[0].id)}catch(e){ElMessage.error(getErrorMessage(e))}}async function create(){if(!form.problemIds.length)return;try{const value=await trainingApi.createVirtualSession(form);dialog.value=false;await load();await open(value.id)}catch(e){ElMessage.error(getErrorMessage(e))}}onMounted(()=>{void load();timer=window.setInterval(()=>now.value=Date.now(),1000)});onBeforeUnmount(()=>{if(timer)clearInterval(timer)});</script>
<style scoped>.virtual-page{max-width:1180px;margin:0 auto;padding:28px 20px}.virtual-page>header,.session-head{display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid #dcdfe6;padding-bottom:18px;margin-bottom:20px}h1,h2,p{margin:0}.virtual-page header p{color:#606266;margin-top:6px}.layout{display:grid;grid-template-columns:260px 1fr;gap:24px}.layout aside{border-right:1px solid #dcdfe6;padding-right:12px}.layout aside button{display:grid;width:100%;border:0;background:transparent;text-align:left;padding:12px;cursor:pointer}.layout aside button.active{background:#ecf5ff}.layout aside span{color:#606266;font-size:13px}.session-head strong{font:600 28px ui-monospace,monospace}@media(max-width:720px){.layout{grid-template-columns:1fr}.layout aside{border-right:0;border-bottom:1px solid #dcdfe6}}</style>
